DIMS = [('Năm', D['dims']['y']), ('Ngành hàng', D['dims']['c']), ('Quốc gia', D['dims']['k']), ('Phân khúc', D['dims']['s'])]


@app.callback(Output('tree-path', 'data'),
              Input({'t': 'node', 'i': ALL, 'k': ALL}, 'n_clicks'),
              Input({'t': 'dim', 'i': ALL}, 'value'),
              State('tree-path', 'data'), prevent_initial_call=True)
def tree_update(_clicks, _dims, path):
    trig = ctx.triggered_id
    if not trig or not ctx.triggered[0]['value']:
        return path
    i = trig['i']
    if i >= len(path):
        return path
    if trig['t'] == 'dim' and ctx.triggered[0]['value'] == path[i]['dim']:
        return path  # dropdown vừa được tạo lại, không đổi gì
    path = path[:i + 1]
    if trig['t'] == 'node':
        path[i]['sel'] = int(trig['k'])
        used = [p['dim'] for p in path]
        nxt = next((j for j in range(4) if j not in used), None)
        if nxt is not None:
            path.append({'dim': nxt, 'sel': None})
    else:
        path[i] = {'dim': ctx.triggered[0]['value'], 'sel': None}
    return path


@app.callback(Output('tree', 'children'), Input('tree-path', 'data'), Input('tm', 'value'))
def tree_render(path, M):
    fm = (lambda v: f(v)) if M == 6 else (lambda v: '$' + k(v))
    rows = D['cube']
    used = [p['dim'] for p in path]
    tot = sum(r[M] for r in rows)
    cols = []
    for i, lv in enumerate(path):
        ag = {}
        for r in rows:
            ag[r[lv['dim']]] = ag.get(r[lv['dim']], 0) + r[M]
        en = sorted(ag.items(), key=lambda e: -e[1])
        sm = sum(v for _, v in en)
        opts = [{'label': (f'Tổng {fm(tot)} · theo ' if i == 0 else 'Theo ') + d[0], 'value': j,
                 'disabled': j in used and j != lv['dim']} for j, d in enumerate(DIMS)]
        cols.append(html.Div(className='col', children=[
            dcc.Dropdown(id={'t': 'dim', 'i': i}, options=opts, value=lv['dim'], clearable=False, searchable=False),
            *[html.Button(id={'t': 'node', 'i': i, 'k': q},
                          className='nd on' if lv['sel'] == q else 'nd',
                          children=[html.Span(DIMS[lv['dim']][1][q]), html.B(f'{fm(v)} · {v / sm * 100:.0f}%'),
                                    html.I(style={'width': f'{v / en[0][1] * 100}%'})])
              for q, v in en]]))
        if lv['sel'] is None:
            break
        rows = [r for r in rows if r[lv['dim']] == lv['sel']]
    return cols


