    pct(c3)
    c4 = go.Figure([go.Bar(x=d['l'], y=d['o'], name='Số đơn', marker_color=PAL[2], yaxis='y'),
                    go.Scatter(x=d['l'], y=d['mg'], name='Biên LN %', mode='lines+markers+text', line=dict(color=P5, width=3),
                               text=[f'{v:.1f}' for v in d['mg']], textposition='top center', yaxis='y2')])
    c4.update_layout(yaxis2=dict(overlaying='y', side='right', range=[0, 30], ticksuffix='%', showgrid=False))
    c5 = go.Figure([go.Bar(x=c['n'], y=c['rev'], name='Doanh thu', marker_color=PAL[0]),
                    go.Scatter(x=c['n'], y=c['p'], name='Lợi nhuận', mode='lines+markers', line=dict(color=P5, width=3))])
    c6 = go.Figure([go.Scatter(x=m['l'], y=D['mm'], name='Biên LN %', mode='lines+markers', line=dict(color=P4, width=3), marker=dict(size=4)),
                    go.Scatter(x=m['l'], y=trend_line(D['mm']), name='Đường xu hướng', line=dict(color=PURPLE, dash='dash', width=2))])
    c6.update_xaxes(nticks=12)
    c6.update_yaxes(range=[15, 28], ticksuffix='%')

    def waterfall(items, base):
        cum, lo, hi, col, lb = base, [], [], [], []
        for it in items:
            if it.get('t'):
                lo.append(base); hi.append(it['v']); col.append(P5); lb.append('$' + k(it['v'])); cum = it['v']
            else:
                n = cum + it['v']
                lo.append(min(cum, n)); hi.append(max(cum, n)); col.append(GOOD if it['v'] >= 0 else P4)
                lb.append(('+' if it['v'] >= 0 else '−') + '$' + k(abs(it['v']))); cum = n
        fig = go.Figure(go.Bar(x=[i['l'] for i in items], y=[h - l for l, h in zip(lo, hi)], base=lo, marker_color=col, text=lb, textposition='outside'))
        fig.update_yaxes(range=[base, None])
        return fig_base(fig, legend=False)

    c7 = waterfall([{'l': 'Giá niêm yết', 'v': W['g'], 't': 1}, {'l': 'Chiết khấu', 'v': -W['di']}, {'l': 'Phí vận chuyển', 'v': W['sh']},
                    {'l': 'Thuế', 'v': W['tx']}, {'l': 'Doanh thu thực thu', 'v': W['rv'], 't': 1}], 0)
    c8 = waterfall([{'l': 'LN 2023', 'v': W['p23'], 't': 1}] + [{'l': n, 'v': W['dp'][i]} for i, n in enumerate(W['cn'])] +
                   [{'l': 'LN 2026', 'v': W['p26'], 't': 1}], 450000)

    c9 = go.Figure([go.Scatter(x=[p['x'] for p in g], y=[p['y'] for p in g], mode='markers+text', name=D['scn'][i],
                               text=[f"{p['k']} {p['y']}%" if p['top'] else '' for p in g], textposition='top center',
                               marker=dict(size=12, color=PAL[i], line=dict(color='#fff', width=1.5)))
                    for i, g in enumerate(D['sc'])])
    c9.update_xaxes(title='Doanh thu ($)', showgrid=True, gridcolor=GRID)
    c9.update_yaxes(title='Biên lợi nhuận %')

    Q = D['dl']
    n = len(Q['x'])
    mx, my = sum(Q['x']) / n, sum(Q['y']) / n
    bb = sum((v - mx) * (Q['y'][i] - my) for i, v in enumerate(Q['x'])) / sum((v - mx) ** 2 for v in Q['x'])
    c10 = go.Figure([go.Scatter(x=Q['x'], y=Q['y'], mode='markers+text', name='Ngày giao', text=[f'{v:.2f}' for v in Q['y']], textposition='top center',
                                marker=dict(size=[8 + (v ** .5) / 4.5 for v in Q['n']], color=P4, opacity=.8)),
                     go.Scatter(x=[0, 13], y=[my + bb * (x - mx) for x in (0, 13)], name='Xu hướng', line=dict(color=PURPLE, dash='dash'))])
    c10.update_xaxes(title='Số ngày giao hàng', showgrid=True, gridcolor=GRID)
    c10.update_yaxes(title='Điểm đánh giá TB', range=[3.3, 4.3])

    return html.Div([
        html.H2('Tăng trưởng không đi kèm lợi nhuận'),
        html.P('So sánh doanh thu và lợi nhuận năm 2026 với 2025. Cột doanh thu cao hơn cột lợi nhuận nghĩa là tăng trưởng đang kém chất lượng.', className='sub'),
        html.Div(className='g', children=[
            card('Chênh lệch tăng trưởng theo ngành hàng (YoY 2026)', '% thay đổi doanh thu và lợi nhuận', graph(fig_base(c1))),
            card('Bản đồ ngành hàng: quy mô và biên lợi nhuận', 'Trục ngang: doanh thu · trục dọc: biên LN % · kích thước bóng: số đơn', graph(fig_base(c2, legend=False))),
            card('Chênh lệch tăng trưởng theo thị trường (YoY 2026)', '% thay đổi doanh thu và lợi nhuận theo quốc gia', graph(fig_base(c3))),
            card('Giá của chiết khấu: biên lợi nhuận theo mức giảm giá', 'Cột: số đơn · đường: biên LN %', graph(fig_base(c4))),
            card('Doanh thu và lợi nhuận theo ngành hàng', 'Cột: doanh thu · đường: lợi nhuận', graph(fig_base(c5))),
            card('Biên lợi nhuận theo tháng', '% lợi nhuận trên doanh thu, kèm xu hướng', graph(fig_base(c6)))]),
        html.H2('Waterfall: dòng tiền đi đâu?'),
        html.Div(className='g', children=[
            card('Cầu nối từ giá niêm yết đến doanh thu thực thu', 'Giá niêm yết − chiết khấu + phí vận chuyển + thuế', graph(c7)),
            card('Cầu nối lợi nhuận 2023 → 2026 theo ngành hàng', 'Ngành nào kéo lợi nhuận lên, ngành nào kéo xuống (trục bắt đầu từ $450K)', graph(c8))]),
        html.H2('Scatter: tìm điểm bất thường'),
        html.Div(className='g', children=[
            card('Phân tán thị trường: quy mô và biên lợi nhuận', 'Mỗi điểm là một cặp ngành hàng × quốc gia; nhãn là 6 điểm doanh thu lớn nhất', graph(fig_base(c9, 380))),
            card('Thời gian giao hàng và mức hài lòng', 'Mỗi điểm là một số ngày giao; kích thước theo số đơn', graph(fig_base(c10, 380)))])])


