# TRANG 6 · INSIGHT & CẢNH BÁO
# ----------------------------------------------------------------------------
def page6():
    c, q, A = D['cat'], D['ctry'], D['alerts']
    tot = sum(c['rev'])
    avg = K['P'] / K['R'] * 100
    hline = lambda x, val, name: go.Scatter(x=x, y=[val] * len(x), name=name, line=dict(color=PURPLE, dash='dash', width=2))
    tagc = {'Cao': ('#FCE1EA', '#C2325F'), 'Trung bình': ('#FFE9DD', '#B5651D'), 'Theo dõi': ('#E6F5EC', '#2F8A62')}
    tag = lambda l: html.Span(l, className='tg', style={'background': tagc[l][0], 'color': tagc[l][1]})

    items = sorted([(n, c['gr'][i] - c['gp'][i]) for i, n in enumerate(c['n'])] +
                   [(n, q['gr'][i] - q['gp'][i]) for i, n in enumerate(q['n'])], key=lambda a: -a[1])[:10]
    g1 = go.Figure(go.Bar(y=[a[0] for a in items][::-1], x=[a[1] for a in items][::-1], orientation='h',
                          marker_color=[P5 if a[1] > 0 else PAL[0] for a in items][::-1],
                          text=[f'{a[1]:.1f}' for a in items][::-1], textposition='outside'))
    g2 = go.Figure([go.Bar(x=D['disc']['l'], y=D['disc']['mg'], name='Biên lợi nhuận',
                           marker_color=[P5 if v < avg else PAL[0] for v in D['disc']['mg']],
                           text=[f'{v:.1f}%' for v in D['disc']['mg']], textposition='outside'),
                    hline(D['disc']['l'], avg, f'Biên trung bình {avg:.1f}%')])
    g2.update_yaxes(ticksuffix='%')
    g3 = go.Figure(go.Bar(x=c['n'], y=[v / tot * 100 for v in c['rev']], marker_color=[P5] + [PAL[0]] * 7,
                          text=[f'{v / tot * 100:.1f}%' for v in c['rev']], textposition='outside'))
    g3.update_yaxes(ticksuffix='%')
    cx = [v / y['o'][i] * 100 for i, v in enumerate(y['st']['Cancelled'])]
    rr = [v / y['o'][i] * 100 for i, v in enumerate(y['st']['Returned'])]
    g4 = go.Figure([go.Bar(x=Y, y=rr, name='Hoàn trả', marker_color=PAL[1], text=[f'{v:.1f}%' for v in rr], textposition='inside'),
                    go.Bar(x=Y, y=cx, name='Hủy', marker_color=PAL[2], text=[f'{v:.1f}%' for v in cx], textposition='inside'),
                    go.Scatter(x=Y, y=D['fail'], name='Tổng thất bại', mode='lines+markers+text', line=dict(color=P5, width=3),
                               text=[f'{v}%' for v in D['fail']], textposition='top center')])
    g4.update_yaxes(ticksuffix='%')
    g5 = go.Figure([go.Bar(x=c['n'], y=c['ret'], name='Hoàn trả %', marker_color=[P5 if v > K['rt'] else PAL[0] for v in c['ret']],
                           text=[f'{v:.1f}%' for v in c['ret']], textposition='outside'),
                    hline(c['n'], K['rt'], f"Trung bình {K['rt']}%")])
    g5.update_yaxes(ticksuffix='%')
    rv = D['cust']['ret']
    ra = sum(rv) / 3
    g6 = go.Figure([go.Bar(x=D['cust']['retl'], y=rv, name='Retention', marker_color=PAL[1], text=[f'{v:.1f}%' for v in rv], textposition='outside'),
                    hline(D['cust']['retl'], ra, f'Trung bình {ra:.1f}%')])
    g6.update_yaxes(range=[0, 100], ticksuffix='%')
    hm = heat(D['hm2']['r'], D['hm2']['c'], D['hm2']['m'], lambda v: f'{v:.1f}%', 110)

    figs = [g1, g2, g3, g4, g5, g6]
    cnt = lambda l: sum(1 for a in A if a[0] == l)
    return html.Div([
        html.H2('Insight và cảnh báo'),
        html.Div(className='g', children=[
            span(4, kpi('Cảnh báo mức cao', cnt('Cao'), 'cần xử lý ngay', cls='bad')),
            span(4, kpi('Cảnh báo trung bình', cnt('Trung bình'), 'cần theo sát')),
            span(4, kpi('Cần theo dõi', cnt('Theo dõi'), 'rủi ro dài hạn', cls='ok')),
            *[html.Div(className='card s6', children=[html.H3([tag(a[0]), a[1]]), html.P(a[2], className='sub'),
                                                       html.Div(graph(fig_base(figs[i], 300, legend=len(figs[i].data) > 1)), className='ch')])
              for i, a in enumerate(A)],
            card('Heat map điểm nóng hoàn trả: ngành hàng × quốc gia', '% đơn bị hoàn trả, ô đậm là điểm nóng cần xử lý', hm, 12)])])


