@app.callback(Output('main', 'children'), Output('nav', 'children'), Input('url', 'hash'))
def route(h):
    pid = (h or '#p1').lstrip('#')
    if pid not in PAGES:
        pid = 'p1'
    nav = [dcc.Link(lb, href=f'/#{v}', className='on' if v == pid else '', refresh=False) for v, lb in TABS]
    return html.Section(PAGES[pid](), className='pg on'), nav


